    opFitSpline(context, id + "e2", { "points" : [vector(30, 0, 0) * millimeter, vector(22.5, 12.5, 4) * millimeter, vector(15, 25, 0) * millimeter] });
    opFitSpline(context, id + "e3", { "points" : [vector(15, 25, 0) * millimeter, vector(7.5, 12.5, 4) * millimeter, vector(0, 0, 0) * millimeter] });
    fill(context, id + "fill1", { "edges" : [{ "entities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "e1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "e2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "e3", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]), "continuity" : GeometricContinuity.G0 }], "surfaceOperationType" : NewSurfaceOperationType.NEW });
    return { "faces" : surfaceProbe(context, qOwnedByBody(qBodyType(qCreatedBy(id + "fill1", EntityType.BODY), BodyType.SHEET), EntityType.FACE)) };
}

